// Adapter scaffold generated by @hexagen/sync — implemented for lane DTP (merge policy).
/**
 * MergePolicyAdapter implements MergePolicyPort: it maps one injected, read-only installation
 * read into one typed answer. It performs no I/O of its own, keeps no cache and writes nothing.
 *
 * The read arrives through a seam because `@fleet/work-execution` does not depend on
 * `@fleet/installation`; the composition root binds the seam to `resolveMergePolicy`.
 *
 * Every value is read through own data properties only, so a getter never runs. An unreadable,
 * invalid or malformed read is `unknown` with a code, never a default and never an echo of the
 * thrown message, a path or a configured value.
 */

import type {
  MergePolicyAnswer,
  MergePolicyDaemonSettings,
  MergePolicyPort,
  MergePolicyRepository,
  MergePolicySource,
  MergePolicyVetoMode,
} from '../../application/ports/out/MergePolicyPort.out-port.js';

export interface MergePolicyAdapterOptions {
  /**
   * Reads the installation (read-only) and answers the merge-policy sections at
   * their revision. It must perform a fresh read on every call and must never
   * write. It may throw when the installation cannot be read.
   * The later composition lane binds this to @fleet/installation; this lane
   * does not, because @fleet/work-execution does not depend on that package.
   */
  readonly readInstallation: () => Promise<MergePolicySource>;
}

const MAX_REPOSITORIES = 256;
const MAX_REQUIRED_CONTEXTS = 16;
const MAX_CONTEXT_LENGTH = 64;
const MAX_TEXT_LENGTH = 256;
const REVISION_PATTERN = /^[0-9a-f]{12}$/;
const VETO_MODES: readonly string[] = ['off', 'shadow', 'live'];
const REPOSITORY_KEYS: readonly string[] = [
  'owner',
  'repo',
  'repositoryKey',
  'projectId',
  'shadow',
  'unattended',
  'requiredContexts',
  'updateBranch',
  'macosProcedure',
  'maxAttempts',
  'checksGraceMinutes',
  'veto',
];
const VETO_KEYS: readonly string[] = ['mode', 'holdConfidence'];
const DAEMON_KEYS: readonly string[] = ['intervalSeconds', 'budgetSeconds', 'settleSeconds'];

const UNREADABLE: MergePolicyAnswer = Object.freeze({
  outcome: 'unknown',
  reason: 'installation-unreadable',
});
const POLICY_INVALID: MergePolicyAnswer = Object.freeze({
  outcome: 'unknown',
  reason: 'policy-invalid',
});
const INSTALLATION_INVALID: MergePolicyAnswer = Object.freeze({
  outcome: 'unknown',
  reason: 'installation-invalid',
});

function isPlainObject(value: unknown): value is object {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value) as unknown;
  return proto === Object.prototype || proto === null;
}

function ownValue(record: object, key: string): unknown {
  return Object.getOwnPropertyDescriptor(record, key)?.value;
}

/**
 * The resolved data must carry exactly the declared fields — no extra field of any
 * name (own property or symbol) may ride along. A record with an unexpected key is
 * malformed and makes the whole answer unknown.
 */
function hasExactlyKeys(record: object, expectedKeys: readonly string[]): boolean {
  const expected = new Set<string>(expectedKeys);
  let seen = 0;
  for (const key of Object.getOwnPropertyNames(record)) {
    if (!expected.has(key)) {
      return false;
    }
    seen += 1;
  }
  if (seen !== expected.size) {
    return false;
  }
  return Object.getOwnPropertySymbols(record).length === 0;
}

function isDenseArray(value: unknown, maxLength: number): value is readonly unknown[] {
  if (!Array.isArray(value) || value.length > maxLength) {
    return false;
  }
  for (let index = 0; index < value.length; index += 1) {
    const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
    if (descriptor === undefined || !('value' in descriptor)) {
      return false;
    }
  }
  return true;
}

/**
 * Copies a dense array's element values through own data properties only, so an
 * array's iterator is never touched: a custom iterator or an iterator getter can
 * neither run nor substitute values for the actual slots.
 */
function readDenseArrayElements(value: unknown, maxLength: number): readonly unknown[] | undefined {
  if (!isDenseArray(value, maxLength)) {
    return undefined;
  }
  const elements: unknown[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
    if (descriptor === undefined || !('value' in descriptor)) {
      return undefined;
    }
    elements.push(descriptor.value);
  }
  return Object.freeze(elements);
}

function isBoundedText(value: unknown, maxLength: number): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= maxLength;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 1;
}

function readRequiredContexts(value: unknown): readonly string[] | undefined {
  const elements = readDenseArrayElements(value, MAX_REQUIRED_CONTEXTS);
  if (elements === undefined) {
    return undefined;
  }
  const contexts: string[] = [];
  for (const entry of elements) {
    if (!isBoundedText(entry, MAX_CONTEXT_LENGTH)) {
      return undefined;
    }
    contexts.push(entry);
  }
  return Object.freeze(contexts);
}

function readVeto(
  value: unknown,
): { readonly mode: MergePolicyVetoMode; readonly holdConfidence: number } | undefined {
  if (!isPlainObject(value)) {
    return undefined;
  }
  const mode = ownValue(value, 'mode');
  const holdConfidence = ownValue(value, 'holdConfidence');
  if (typeof mode !== 'string' || !VETO_MODES.includes(mode)) {
    return undefined;
  }
  if (typeof holdConfidence !== 'number' || !Number.isFinite(holdConfidence)) {
    return undefined;
  }
  if (holdConfidence < 0 || holdConfidence > 1) {
    return undefined;
  }
  if (!hasExactlyKeys(value, VETO_KEYS)) {
    return undefined;
  }
  return Object.freeze({ mode: mode as MergePolicyVetoMode, holdConfidence });
}

function readRepository(value: unknown): MergePolicyRepository | undefined {
  if (!isPlainObject(value)) {
    return undefined;
  }
  const owner = ownValue(value, 'owner');
  const repo = ownValue(value, 'repo');
  const repositoryKey = ownValue(value, 'repositoryKey');
  const projectId = ownValue(value, 'projectId');
  const shadow = ownValue(value, 'shadow');
  const unattended = ownValue(value, 'unattended');
  const updateBranch = ownValue(value, 'updateBranch');
  const macosProcedure = ownValue(value, 'macosProcedure');
  const maxAttempts = ownValue(value, 'maxAttempts');
  const checksGraceMinutes = ownValue(value, 'checksGraceMinutes');
  const requiredContexts = readRequiredContexts(ownValue(value, 'requiredContexts'));
  const veto = readVeto(ownValue(value, 'veto'));
  if (
    !isBoundedText(owner, MAX_TEXT_LENGTH) ||
    !isBoundedText(repo, MAX_TEXT_LENGTH) ||
    !isBoundedText(repositoryKey, MAX_TEXT_LENGTH) ||
    !isBoundedText(projectId, MAX_TEXT_LENGTH) ||
    typeof shadow !== 'boolean' ||
    typeof unattended !== 'boolean' ||
    typeof updateBranch !== 'boolean' ||
    !(macosProcedure === null || isBoundedText(macosProcedure, MAX_TEXT_LENGTH)) ||
    !isPositiveInteger(maxAttempts) ||
    !isPositiveInteger(checksGraceMinutes) ||
    requiredContexts === undefined ||
    veto === undefined ||
    !hasExactlyKeys(value, REPOSITORY_KEYS) ||
    repositoryKey !== `${owner}/${repo}`
  ) {
    return undefined;
  }
  return Object.freeze({
    owner,
    repo,
    repositoryKey,
    projectId,
    shadow,
    unattended,
    requiredContexts,
    updateBranch,
    macosProcedure,
    maxAttempts,
    checksGraceMinutes,
    veto,
  });
}

function readRepositories(value: unknown): readonly MergePolicyRepository[] | undefined {
  const elements = readDenseArrayElements(value, MAX_REPOSITORIES);
  if (elements === undefined) {
    return undefined;
  }
  const repositories: MergePolicyRepository[] = [];
  for (const entry of elements) {
    const repository = readRepository(entry);
    if (repository === undefined) {
      return undefined;
    }
    repositories.push(repository);
  }
  return Object.freeze(repositories);
}

function readDaemon(value: unknown): MergePolicyDaemonSettings | undefined {
  if (!isPlainObject(value)) {
    return undefined;
  }
  const intervalSeconds = ownValue(value, 'intervalSeconds');
  const budgetSeconds = ownValue(value, 'budgetSeconds');
  const settleSeconds = ownValue(value, 'settleSeconds');
  if (
    typeof intervalSeconds !== 'number' ||
    typeof budgetSeconds !== 'number' ||
    typeof settleSeconds !== 'number' ||
    !Number.isFinite(intervalSeconds) ||
    !Number.isFinite(budgetSeconds) ||
    !Number.isFinite(settleSeconds) ||
    intervalSeconds <= 0 ||
    budgetSeconds <= 0 ||
    settleSeconds < 0 ||
    !hasExactlyKeys(value, DAEMON_KEYS)
  ) {
    return undefined;
  }
  return Object.freeze({ intervalSeconds, budgetSeconds, settleSeconds });
}

function answerFor(source: unknown): MergePolicyAnswer {
  if (!isPlainObject(source)) {
    return INSTALLATION_INVALID;
  }
  const outcome = ownValue(source, 'outcome');
  if (outcome === 'invalid') {
    return POLICY_INVALID;
  }
  if (outcome !== 'resolved') {
    return INSTALLATION_INVALID;
  }
  const policyRevision = ownValue(source, 'policyRevision');
  const repositories = readRepositories(ownValue(source, 'repositories'));
  const daemon = readDaemon(ownValue(source, 'daemon'));
  if (
    typeof policyRevision !== 'string' ||
    !REVISION_PATTERN.test(policyRevision) ||
    repositories === undefined ||
    daemon === undefined
  ) {
    return INSTALLATION_INVALID;
  }
  return Object.freeze({ outcome: 'known', policyRevision, repositories, daemon });
}

export class MergePolicyAdapter implements MergePolicyPort {
  constructor(private readonly options: MergePolicyAdapterOptions) {}

  async readMergePolicy(): Promise<MergePolicyAnswer> {
    let source: unknown;
    try {
      source = await this.options.readInstallation();
    } catch {
      return UNREADABLE;
    }
    try {
      return answerFor(source);
    } catch {
      return INSTALLATION_INVALID;
    }
  }
}
